package world

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// TestMain 支持以子进程方式运行多进程并发测试。
func TestMain(m *testing.M) {
	switch os.Getenv("WORLD_TEST_HELPER") {
	case "":
		os.Exit(m.Run())
	case "concurrent_replace":
		helperConcurrentReplace()
		os.Exit(0)
	case "generate_world":
		helperGenerateWorld()
		os.Exit(0)
	default:
		fmt.Fprintln(os.Stderr, "unknown helper")
		os.Exit(2)
	}
}

func newTestArchive(t *testing.T) (*Archive, string) {
	t.Helper()
	dir := t.TempDir()
	a, err := Create(dir)
	if err != nil {
		t.Fatalf("Create: %v", err)
	}
	return a, dir
}

func TestSaveDuplicateSlot(t *testing.T) {
	a, _ := newTestArchive(t)
	w := baseWorld(t)
	if _, err := a.Save("slot1", w); err != nil {
		t.Fatal(err)
	}
	_, err := a.Save("slot1", w)
	var ce *ConflictError
	if !errors.As(err, &ce) {
		t.Fatalf("重名应返回 ConflictError，得到 %T: %v", err, err)
	}
}

func TestReplaceRequiresExpectedAndCAS(t *testing.T) {
	a, _ := newTestArchive(t)
	w := baseWorld(t)
	info, err := a.Save("s", w)
	if err != nil {
		t.Fatal(err)
	}

	// 不带记录标识拒绝。
	if _, err := a.Replace("s", w, ""); err == nil {
		t.Fatal("空记录标识应当拒绝")
	}
	// 胡乱的记录标识冲突。
	if _, err := a.Replace("s", w, "rdeadbeef"); err == nil {
		t.Fatal("不存在的记录标识应当冲突")
	}

	// 正常覆盖：父记录是被覆盖的记录。
	if _, err := w.Apply(Commit{Time: 1}); err != nil {
		t.Fatal(err)
	}
	info2, err := a.Replace("s", w, info.ID)
	if err != nil {
		t.Fatalf("Replace: %v", err)
	}
	if info2.Parent != info.ID {
		t.Fatalf("新记录父标识应为 %s，得到 %s", info.ID, info2.Parent)
	}
	if info2.ID == info.ID {
		t.Fatal("每次保存应产生新的唯一标识")
	}

	// 再次用旧标识覆盖 -> 冲突。
	if _, err := a.Replace("s", w, info.ID); err == nil {
		t.Fatal("用过时标识覆盖应冲突")
	} else {
		var ce *ConflictError
		if !errors.As(err, &ce) {
			t.Fatalf("应返回 ConflictError，得到 %T", err)
		}
	}
}

// TestReplaceCurrentRecordMissing 普通覆盖所依据的当前记录文件已被删除时，
// 返回记录不存在错误：槽指向、历史与已有记录保持原样，不产生新记录，传入
// 的世界不被改动；随后仍可通过恢复预览与确认恢复从完好的历史记录恢复。
func TestReplaceCurrentRecordMissing(t *testing.T) {
	a, dir := newTestArchive(t)
	ids := saveN(t, a, "s", 1) // r1(time 1) r0(time 0)
	if err := os.Remove(recordPath(dir, ids[0])); err != nil {
		t.Fatal(err)
	}

	w := baseWorld(t)
	if _, err := w.Apply(Commit{Time: 7}); err != nil {
		t.Fatal(err)
	}
	before := recordCount(t, a)
	_, err := a.Replace("s", w, ids[0])
	var nfe *NotFoundError
	if !errors.As(err, &nfe) {
		t.Fatalf("当前记录缺失应返回 NotFoundError，得到 %T: %v", err, err)
	}
	if nfe.Record != ids[0] {
		t.Fatalf("错误应指出缺失的记录 %s，得到 %+v", ids[0], nfe)
	}

	// 槽仍指向原标识，历史与记录文件不变，传入的世界保持原状态。
	p, err := a.readSlotPointerLocked("s")
	if err != nil {
		t.Fatal(err)
	}
	if p.Latest != ids[0] {
		t.Fatalf("槽指向不应改变: %s -> %s", ids[0], p.Latest)
	}
	if got := recordCount(t, a); got != before {
		t.Fatalf("被拒绝的覆盖不应产生新记录: %d -> %d", before, got)
	}
	if got := w.Snapshot().Time; got != 7 {
		t.Fatalf("传入的世界不应被改动: 时间片 %d", got)
	}

	// 随后通过恢复预览选择完好的历史记录，仍可确认恢复。
	preview, err := a.PreviewRecovery("s", []string{"v1"})
	if err != nil {
		t.Fatal(err)
	}
	if preview.Current != ids[0] || preview.Source != ids[1] {
		t.Fatalf("预览应选中完好的历史记录: %+v", preview)
	}
	if _, err := a.ConfirmRecovery("s", preview.Current, preview.Source, []string{"v1"}); err != nil {
